package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamEconomyDevBank2 {
  private const val T = "ආර්ථික ක්‍රම, සුබසාධනය, බහුසංස්කෘතික සමාජය හා තිරසාර සංවර්ධනය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ආර්ථික විද්‍යාවේදී භාණ්ඩ හා සේවා නිෂ්පාදනය සඳහා යොදාගන්නා ප්‍රධාන නිෂ්පාදන සාධක හතර මොනවාද?", "භූමිය, ශ්‍රමය, ප්‍රාග්ධනය සහ ව්‍යවසායකත්වය", "මුදල්, බදු, රේගු සහ පොලිය", "නීතිය, අධිකරණය, පොලිසිය සහ හමුදාව", "ආනයනය, අපනයනය, ප්‍රවාහනය සහ ගබඩාව", "ඕනෑම ආර්ථික ක්‍රමයක නිෂ්පාදන ක්‍රියාවලියට මෙම සාධක හතර අත්‍යවශ්‍ය වේ."),
    q("විකල්ප අවස්ථා කිහිපයක් අතුරින් එකක් තෝරා ගැනීමේදී අත්හැර දැමීමට සිදුවන ඊළඟ හොඳම විකල්පයේ වටිනාකම කුමක්ද?", "ආවස්ථික පිරිවැය (Opportunity Cost)", "ආන්තික ආදායම", "ස්ථාවර පිරිවැය", "උද්ධමන අනුපාතය", "සම්පත් හිඟකම නිසා තේරීමක් කරන සෑම විටම ආවස්ථික පිරිවැයක් හටගනී."),
    q("වෙළඳපොළ ආර්ථික ක්‍රමයක නිෂ්පාදන සාධක සතු අයිතිය බහුලවම පවතින්නේ කා අතේද?", "පෞද්ගලික අංශය හා පුද්ගලයන් අතේ", "මධ්‍යම රජය අතේ පමණි", "හමුදා අධිකාරිය අතේ", "පළාත් සභා ආණ්ඩුකාරවරයා අතේ", "පෞද්ගලික දේපළ අයිතිය නිදහස් වෙළඳපොළ ආර්ථිකයේ මූලික ලක්ෂණයකි."),
    q("සමාජවාදී ආර්ථික ක්‍රමයේ මූලික න්‍යායාත්මක පදනම ඉදිරිපත් කළ ප්‍රධාන දාර්ශනිකයන් දෙදෙනා කවුද?", "කාල් මාක්ස් සහ ෆෙඩ්රික් එංගල්ස්", "ඇඩම් ස්මිත් සහ ඩේවිඩ් රිකාඩෝ", "ජෝන් ලොක් සහ මොන්ටෙස්කියු", "ඒ.වී. ඩයිසි සහ අයිවර් ජෙනිංස්", "සමාජ අසමානතාව තුරන් කර සම්පත් සමාජ සතු කිරීමේ සමාජවාදී චින්තනය ඔවුන් ඉදිරිපත් කළහ."),
    q("ශ්‍රී ලංකාවේ නිදහසින් පසු ප්‍රථම දශක කිහිපය තුළ රජය ප්‍රධාන කර්මාන්ත හා ප්‍රවාහන සේවා ජනසතු කිරීමෙන් පිළිබිඹු වූයේ කුමන ප්‍රතිපත්තියද?", "රාජ්‍ය කේන්ද්‍රීය සුබසාධන හා සමාජවාදී නැඹුරුවක් සහිත ආර්ථික ප්‍රතිපත්තිය", "සම්පූර්ණ විදේශීය ඒකාධිකාරය", "වැඩවසම් රදළ ක්‍රමය", "බදු රහිත වෙළඳ කලාප ක්‍රමය", "ලංගම, ඛනිජ තෙල් සංස්ථාව හා මහජන බැංකුව වැනි ආයතන රාජ්‍ය හිමිකාරිත්වය යටතේ බිහි විය."),
    q("විවෘත ආර්ථික ප්‍රතිපත්තිය යටතේ රටකට ඇති විය හැකි ප්‍රධාන අවාසිදායක තත්ත්වයක් කුමක්ද?", "විදේශීය ආනයන තරගය හමුවේ දේශීය සුළු කර්මාන්ත හා දේශීය නිෂ්පාදන බිඳ වැටීම", "අන්තර්ජාල සබඳතා සම්පූර්ණයෙන් නැති වීම", "වෙළඳසැල්වල භාණ්ඩ හිඟ වීම", "තාක්ෂණය රටට නොපැමිණීම", "ආනයන බාධක ලිහිල් කිරීමෙන් ලාභ විදේශ භාණ්ඩ සමඟ තරග කිරීමට දේශීය නිෂ්පාදකයන්ට අපහසු වේ."),
    q("ශ්‍රී ලංකාවේ 'නිදහස් සෞඛ්‍ය සේවාව' මඟින් සාමාන්‍ය ජනතාවට හිමිවන ප්‍රධානතම ප්‍රතිලාභය කුමක්ද?", "සියලුම රජයේ රෝහල්වලින් නොමිලේ වෛද්‍ය ප්‍රතිකාර, ශල්‍යකර්ම හා ඖෂධ ලැබීම", "විදේශ ගුවන් ටිකට්පත් නොමිලේ ලැබීම", "පෞද්ගලික රක්ෂණ ගාස්තු අනිවාර්ය වීම", "ප්‍රතිශක්තිකරණ එන්නත් නතර කිරීම", "මව් හා ළදරු මරණ අනුපාතය අඩු කර ඉහළ ආයු අපේක්ෂාවක් ළඟා කර ගැනීමට නිදහස් සෞඛ්‍යය ඉවහල් විය."),
    q("ප්‍රජා සෞඛ්‍ය සේවාවේදී බෝවන රෝග පාලනයට සහ මාතෘ සායන පවත්වාගැනීමට ග්‍රාමීය මට්ටමින් සේවය කරන නිලධාරිනිය කවුද?", "පවුල් සෞඛ්‍ය සේවා නිලධාරිනිය (Public Health Midwife)", "විගණන පරීක්ෂකවරිය", "තේරීම් භාර නිලධාරිනිය", "නගර සභා නීතිඥවරිය", "සෞඛ්‍ය වෛද්‍ය නිලධාරී (MOH) කාර්යාල හරහා බිම් මට්ටමේ පෝෂණ හා ප්‍රතිශක්තිකරණ සේවා ඇය ඉටු කරයි."),
    q("වැඩිහිටි පුරවැසියන්ට විශ්‍රාම කාලයේ ආර්ථික සුරක්ෂිතතාව ලබාදීමට පෞද්ගලික අංශයේ සේවකයන් වෙනුවෙන් ක්‍රියාත්මක අරමුදල කුමක්ද?", "සේවක අර්ථසාධක අරමුදල (EPF) සහ සේවා නියුක්තයන්ගේ භාර අරමුදල (ETF)", "මහපොළ ශිෂ්‍යත්ව අරමුදල", "නාගරික සංවර්ධන අරමුදල", "සමථ මණ්ඩල අරමුදල", "සේවකයාගේ සහ සේවායෝජකයාගේ දායකත්වයෙන් විශ්‍රාම ගැනීමේදී ප්‍රතිලාභ සලසන සමාජ ආරක්ෂණ ක්‍රමය මෙයයි."),
    q("රටේ සුබසාධන වැඩසටහන් 'ඉලක්කගත කිරීම' (Targeted Welfare) යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "සැබවින්ම ආර්ථික අවශ්‍යතාව ඇති දිළිඳුම හා අවදානමට ලක්වූ කණ්ඩායම් තෝරා ආධාර දීම", "ධනවත් ව්‍යාපාරිකයන්ට පමණක් ආධාර දීම", "සියලු විදේශිකයන්ට වැටුප් ගෙවීම", "වැඩිහිටි නිවාස වසා දැමීම", "සීමිත රාජ්‍ය අරමුදල් නාස්ති නොවී සැබෑ දුප්පත් පවුල් වෙත යොමු කිරීම ඉලක්කගත සුබසාධනයේ අරමුණයි."),
    q("රටක අයවැය හිඟයක් (Budget Deficit) ඇති වන්නේ කුමන අවස්ථාවකදීද?", "රජයේ මුළු වියදම, රජයේ මුළු ආදායම ඉක්මවා ගිය විට", "රජයේ ආදායම වියදමට වඩා විශාල ලෙස වැඩි වූ විට", "විදේශ ආයෝජන දෙගුණ වූ විට", "සියලුම බදු අහෝසි කළ විට", "රජයේ ආදායමට වඩා වියදම වැඩි වූ විට එම පරතරය පියවීමට දේශීය හා විදේශීය ණය ගැනීමට සිදුවේ."),
    q("භාණ්ඩ හා සේවාවල සාමාන්‍ය මිල මට්ටම අඛණ්ඩව ඉහළ යාම හේතුවෙන් මුදලේ ක්‍රය ශක්තිය (මිලදී ගැනීමේ හැකියාව) අඩුවීම කුමක්ද?", "උද්ධමනය (Inflation)", "අවධමනය (Deflation)", "ආර්ථික ස්ථාවරත්වය", "සමතුලිත අයවැය", "උද්ධමනය ඉහළ ගිය විට එකම මුදලකින් මිලදී ගත හැකි භාණ්ඩ ප්‍රමාණය අඩුවේ."),
    q("ශ්‍රී ලංකාවේ මුදල් නෝට්ටු හා කාසි නිකුත් කිරීමේ හා මුදල් ප්‍රතිපත්තිය මෙහෙයවීමේ පූර්ණ බලය ඇති ආයතනය කුමක්ද?", "ශ්‍රී ලංකා මහ බැංකුව (Central Bank of Sri Lanka)", "විගණකාධිපති දෙපාර්තමේන්තුව", "ශ්‍රී ලංකා රේගුව", "පාරිභෝගික කටයුතු අධිකාරිය", "1949 අංක 58 මුදල් නීති පනත හා 2023 නව මහ බැංකු පනත යටතේ මිල ස්ථායීතාව රැකීම මහ බැංකුවේ වගකීමයි."),
    q("කිසියම් පාරිභෝගිකයෙකුට වෙළඳපොළෙන් මිලදී ගත් දෝෂ සහිත භාණ්ඩයක් සම්බන්ධයෙන් පැමිණිලි කළ හැකි රාජ්‍ය ආයතනය කුමක්ද?", "පාරිභෝගික කටයුතු පිළිබඳ අධිකාරිය (CAA)", "පළාත් පාලන කොමිසම", "රාජ්‍ය සේවා කොමිසම", "පාර්ලිමේන්තු මහලේකම් කාර්යාලය", "1977 කෙටි දුරකථන අංකය හරහා පාරිභෝගික පැමිණිලි ඉදිරිපත් කිරීමට හැකියාව ඇත."),
    q("පාරිභෝගිකයන් සතු 'සෞඛ්‍ය සම්පන්න පරිසරයක ජීවත් වීමේ අයිතිවාසිකම' යටතට ගැනෙන්නේ කුමක්ද?", "පරිසරයට හා සෞඛ්‍යයට අහිතකර රසායනික ද්‍රව්‍ය හා විෂ අඩංගු නොවන නිෂ්පාදන ලැබීම", "ප්ලාස්ටික් අපද්‍රව්‍ය මහ මගට දැමීම", "අධික ශබ්ද දූෂණය ඉවසීම", "කල් ඉකුත් වූ ඖෂධ භාවිතය", "එක්සත් ජාතීන්ගේ පාරිභෝගික ආරක්ෂණ මාර්ගෝපදේශ මඟින් පිරිසිදු පරිසර අයිතියද පිළිගෙන ඇත."),
    q("වෙළඳපොළේ අතරමැදියන් විසින් ගොවියාට අඩු මිලක් ගෙවා පාරිභෝගිකයාගෙන් අධික මිලක් අය කිරීම වැළැක්වීමට යෝග්‍ය ක්‍රමය කුමක්ද?", "සමුපකාර හා සෘජු ගොවි වෙළඳපොළ ජාල ශක්තිමත් කිරීම", "ආනයන බදු සම්පූර්ණයෙන් ඉවත් කිරීම", "කළුකඩ වෙළඳාම දිරිගැන්වීම", "ගොවීන්ට පොහොර නැවැත්වීම", "නිෂ්පාදකයා සහ පාරිභෝගිකයා සෘජුව සම්බන්ධ කිරීමෙන් දෙපාර්ශ්වයටම සාධාරණ මිලක් හිමිවේ."),
    q("භාණ්ඩයක ඇසුරුමෙහි 'සාධාරණ වෙළඳාම' (Fair Trade) යන සංකල්පයෙන් අවධාරණය කෙරෙන්නේ කුමක්ද?", "නිෂ්පාදකයන්ට හා ගොවීන්ට සාධාරණ මිලක් හා ශ්‍රමිකයන්ට යහපත් සේවා තත්ත්වයන් ලබා දීම", "ළමා ශ්‍රමය යොදා ලාභය වැඩි කිරීම", "මිල සඟවා භාණ්ඩ විකිණීම", "පාරිභෝගිකයා රැවටීම", "සදාචාරාත්මක වෙළඳාම හරහා සංවර්ධනය වෙමින් පවතින ප්‍රජාවන්ට සාධාරණ ප්‍රතිලාභ සලසයි."),
    q("වගකිවයුතු පාරිභෝගිකයෙකු සතු 'විවේචනාත්මක විමසිලිමත් බව' (Critical Awareness) යනු කුමක්ද?", "භාණ්ඩයේ මිල, ගුණාත්මක බව හා සැබෑ අවශ්‍යතාව ප්‍රශ්න කරමින් බුද්ධිමත්ව මිලදී ගැනීම", "වෙළඳ දැන්වීම් දුටු පමණින් සියල්ල මිලදී ගැනීම", "කල් ඉකුත් වූ දිනය නොබැලීම", "බිල්පත ප්‍රතික්ෂේප කිරීම", "පාරිභෝගික අයිතිවාසිකම් සමඟ වගකීම්ද ඉටු කිරීමෙන් වෙළඳ වංචා පරාජය කළ හැක."),
    q("වෙළඳපොළේදී 'තනි ඒකාධිකාරයක්' (Monopoly) බිහිවීම පාරිභෝගිකයාට අහිතකර වන්නේ ඇයි?", "විකල්ප සැපයුම්කරුවන් නොමැති වීමෙන් මිල ඉහළ දැමීමට හා ගුණාත්මක බව අඩු කිරීමට ඉඩ ඇති බැවිනි", "භාණ්ඩ මිල ඉතා අඩු වන බැවිනි", "පාරිභෝගික තේරීම අසීමිත වන බැවිනි", "නව තරගකරුවන් බිහිවන බැවිනි", "සාධාරණ තරගකාරිත්වය ආරක්ෂා කිරීමට පාරිභෝගික අධිකාරිය ඒකාධිකාරී හැසිරීම් නියාමනය කරයි."),
    q("ශ්‍රී ලංකාවේ බහුසංස්කෘතික සමාජය තුළ 'සංස්කෘතික අනන්‍යතාව' යනුවෙන් අදහස් කරන්නේ කුමක්ද?", "යම් ජන කණ්ඩායමකට ආවේණික භාෂාව, ඇඳුම් පැළඳුම්, ආහාර රටා, කලා ශිල්ප හා සිරිත් විරිත්", "සියලු දෙනාම එකම නිල ඇඳුම ඇඳීම", "විදේශීය ගමන් බලපත්‍ර අංකය", "ජාතික බදු අංකය", "විවිධ ජන කොටස්වල සංස්කෘතික උරුමයන් පොදු ජාතික උරුමය පොහොසත් කරයි."),
    q("ශ්‍රී ලංකාවේ ප්‍රධාන ආගම් හතර වන බුද්ධාගම, හින්දු, ඉස්ලාම් හා ක්‍රිස්තියානි ආගම් පොදුවේ උගන්වන සදාචාරාත්මක වටිනාකම කුමක්ද?", "සාමය, කරුණාව, ඉවසීම හා අනුන්ට ගරු කිරීම", "වෛරය හා පළිගැනීම", "පරිසර විනාශය", "අන් ආගම් හෙළා දැකීම", "සියලු ආගමික ඉගැන්වීම් සමාජ සමගිය හා මානව ගරුත්වය වර්ධනය කිරීමට මග පෙන්වයි."),
    q("බහුසංස්කෘතික සමාජයක සාමාජිකයන් අතර 'අන්තර්-සංස්කෘතික සංවාදය' (Intercultural Dialogue) ඇති කිරීම වැදගත් වන්නේ ඇයි?", "මිථ්‍යා මත හා බිය දුරු කර විවිධ ප්‍රජාවන් අතර විශ්වාසය ගොඩනැගීමට", "ජන කොටස් වෙන් කර තැබීමට", "සංස්කෘතික උත්සව අඩු කිරීමට", "තනි භාෂාවක් පමණක් පැටවීමට", "විවෘතව හා ගෞරවයෙන් අදහස් හුවමාරු කර ගැනීම ජාතික සංහිඳියාවේ පදනමයි."),
    q("1978 ශ්‍රී ලංකා ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ ජාතික භාෂා සහ රාජ්‍ය භාෂා ලෙස පිළිගෙන ඇති භාෂා මොනවාද?", "සිංහල සහ දෙමළ (ඉංග්‍රීසි සම්බන්ධක භාෂාව ලෙස)", "සිංහල පමණි", "ඉංග්‍රීසි පමණි", "පාලි සහ සංස්කෘත", "13 හා 16 වන සංශෝධන මඟින් සිංහල හා දෙමළ රාජ්‍ය හා ජාතික භාෂා බවට පත් කෙරිණි."),
    q("ශ්‍රී ලංකාවේ ජාතික කොඩියෙහි සිංහ රුවට වම් පසින් ඇති කොළ සහ තැඹිලි පැහැති සිරස් තීරු දෙකෙන් නිරූපණය වන්නේ කුමක්ද?", "මුස්ලිම් සහ දෙමළ ජන කොටස් (සියලු ජාතීන්ගේ එකමුතුව)", "වනාන්තර හා කාන්තාර පමණි", "නාවික හා ගුවන් හමුදා", "පළාත් දෙකක් පමණි", "ශ්‍රී ලංකා ජාතික ධජය රටේ බහුජාතික හා බහුසංස්කෘතික සංයුතිය සංකේතවත් කරයි."),
    q("බහුසංස්කෘතික පාසල් පරිසරයක සිසුන් අතර සමගිය වර්ධනය කිරීමට කළ හැකි ප්‍රායෝගික ක්‍රියාකාරකමක් කුමක්ද?", "සියලු සංස්කෘතීන්ගේ උත්සව හා කලා අංග ඇතුළත් සමගි දින වැඩසටහන් පැවැත්වීම", "එක් කණ්ඩායමක සිසුන් පමණක් ක්‍රීඩා කණ්ඩායමට ගැනීම", "වෙනත් භාෂාවලට සිනාසීම", "පන්ති කාමර ජනවර්ග අනුව වෙන් කිරීම", "සාමූහික ක්‍රීඩා, ශිෂ්‍ය හුවමාරු හා සංස්කෘතික උළෙලවල් සිසුන් අතර සහෝදරත්වය වැඩි කරයි."),
    q("ජාතික සංහිඳියාව ගොඩනැගීමේදී 'විවිධ භාෂා හා සංස්කෘතීන්ට පොදු අවකාශයක් ලබාදීම' යන්නෙන් අදහස් වන්නේ කුමක්ද?", "රාජ්‍ය ආයතනවල, මාර්ග පුවරුවල හා මාධ්‍ය තුළ සියලු ජන කොටස්වල භාෂා සමානව භාවිත කිරීම", "එක් භාෂාවක් පමණක් නාමපුවරුවල තැබීම", "සුළුතර ජනතාවට රාජ්‍ය සේවය තහනම් කිරීම", "පුවත්පත් නැවැත්වීම", "භාෂා සමානාත්මතාව සෑම පුරවැසියෙකුටම තමා රටේ සමාන කොටස්කරුවෙකු බව දැනීමට ඉඩ සලසයි."),
    q("බහුසංස්කෘතික සමාජයක 'ජනවාර්ගික කේන්ද්‍රීයවාදය' (Ethnocentrism) යනු කුමක්ද?", "තමන්ගේම ජනවර්ගය හා සංස්කෘතිය අන් සියල්ලටම වඩා උසස් යැයි සිතා අනෙක් අය පහත් කොට සැලකීම", "සියලු සංස්කෘතීන්ට සමාන ගෞරවය දැක්වීම", "විදෙස් භාෂා ඉගෙනීම", "ජාතික ගීය ගායනා කිරීම", "මෙම පටු ආකල්පය සමාජ බෙදීම්වලට හා වාර්ගික ගැටුම්වලට ප්‍රධාන හේතුවක් වේ."),
    q("තිරසාර සංවර්ධනයේදී 'අන්තර්-පරම්පරා සාධාරණත්වය' (Intergenerational Equity) මඟින් අදහස් කරන්නේ කුමක්ද?", "වර්තමාන පරපුර පරිසර සම්පත් විනාශ නොකර අනාගතයේ උපදින පරපුර වෙනුවෙන්ද ඉතිරි කිරීම", "වත්මන් පරපුර සියලු වනාන්තර කපා භාවිත කිරීම", "අනාගත පරපුරට අධ්‍යාපනය නොදීම", "සියලු ඛනිජ සම්පත් එක් වසරකදී වැය කිරීම", "පෘථිවිය අපට පෙර පරපුරෙන් ලැබුණු තෑග්ගක් පමණක් නොව අනාගත දරුවන්ගෙන් ලබාගත් ණයක් ලෙස සැලකේ."),
    q("එක්සත් ජාතීන්ගේ තිරසාර සංවර්ධන ඉලක්ක (SDGs) අතුරින් 'පළමු ඉලක්කය' වන්නේ කුමක්ද?", "සෑම තැනකම සියලු ආකාරයේ දිළිඳුකම තුරන් කිරීම (No Poverty)", "සඳ මත ජනාවාස තැනීම", "ලෝක බැංකුව වසා දැමීම", "න්‍යෂ්ටික අවි නිපදවීම", "දිළිඳුකම පිටුදැකීම තිරසාර සංවර්ධන න්‍යාය පත්‍රයේ ප්‍රමුඛතම ඉලක්කයයි."),
    q("SDGs 4 වන ඉලක්කය මඟින් ලෝක ප්‍රජාව වෙත අවධාරණය කෙරෙන්නේ කුමන අංශයද?", "සැමට ඇතුළත්, සාධාරණ හා ගුණාත්මක අධ්‍යාපනයක් තහවුරු කිරීම", "වනාන්තර කපා නගර හැදීම", "ප්ලාස්ටික් භාවිතය දෙගුණ කිරීම", "සියලු පාසල් මුදල් අය කරන ආයතන කිරීම", "ගුණාත්මක අධ්‍යාපනය දිළිඳුකමින් මිදීමට හා සමානාත්මතාවයට ඇති ප්‍රධාන මාර්ගයයි."),
    q("SDGs 5 වන ඉලක්කය මඟින් අපේක්ෂා කෙරෙන සමාජීය වෙනස කුමක්ද?", "ස්ත්‍රී පුරුෂ සමානාත්මතාව ළඟා කර ගැනීම සහ සියලු කාන්තාවන් හා ගැහැනු ළමයින් සවිබල ගැන්වීම", "කාන්තාවන්ට ඡන්ද බලය සීමා කිරීම", "පිරිමි ළමයින්ට පමණක් පාසල් විවෘත කිරීම", "වැටුප් විෂමතාව වැඩි කිරීම", "සමාජයේ සෑම ක්ෂේත්‍රයකම ස්ත්‍රී පුරුෂ දෙපාර්ශ්වයටම සමාන අවස්ථා හිමිවිය යුතුය."),
    q("පිරිසිදු ජලය හා සනීපාරක්ෂාව සැමට තහවුරු කිරීම (SDG 6) තිරසාර සංවර්ධනයට වැදගත් වන්නේ ඇයි?", "ජල මූලාශ්‍ර දූෂණය අවම කර රෝග ව්‍යාප්තිය නවතා සෞඛ්‍ය සම්පන්න ජීවිතයක් සැලසීමට", "කර්මාන්තශාලා අපද්‍රව්‍ය ගංගාවලට හැරීමට", "වැව් හා ඇළ මාර්ග ගොඩකිරීමට", "ජල බිල්පත් අසීමිතව වැඩි කිරීමට", "පිරිසිදු පානීය ජලය මානව අයිතිවාසිකමක් මෙන්ම පොදු සෞඛ්‍යයේ පදනමයි."),
    q("පොසිල ඉන්ධන (ගල් අඟුරු, ඛනිජ තෙල්) දහනය හේතුවෙන් පෘථිවි වායුගෝලයේ සිදුවන ප්‍රධාන පාරිසරික ගැටලුව කුමක්ද?", "කාබන් ඩයොක්සයිඩ් ඇතුළු හරිතාගාර වායු වැඩි වී ගෝලීය උණුසුම ඉහළ යාම", "ඔක්සිජන් ප්‍රමාණය සීඝ්‍රයෙන් වැඩි වීම", "සාගර ජල මට්ටම බින්දුවට බැසීම", "හිම කඳු විශාල වීම", "දේශගුණික විපර්යාස, අධික නියඟ සහ අසාමාන්‍ය ගංවතුර තත්ත්වයන්ට මෙය හේතු වේ."),
    q("තිරසාර බලශක්ති කළමනාකරණයේදී පුද්ගලයෙකුට එදිනෙදා ජීවිතයේදී ගත හැකි පහසු පියවරක් කුමක්ද?", "අනවශ්‍ය විදුලි පහන් නිවා දැමීම, LED බල්බ භාවිතය හා පොදු ප්‍රවාහනය යොදාගැනීම", "සෑම විටම ප්ලාස්ටික් පිළිස්සීම", "දවස පුරා ජල කරාම විවෘත කර තැබීම", "පුද්ගලික වාහන පමණක් භාවිත කිරීම", "බලශක්ති සංරක්ෂණය සෑම පුරවැසියෙකුගෙන්ම ආරම්භ කළ හැකි පාරිසරික යුතුකමකි."),
    q("ශ්‍රී ලංකාවේ නාගරික ප්‍රදේශවල බරපතළ පාරිසරික හා සෞඛ්‍ය ගැටලුවක් බවට පත්ව ඇති 'ඝන අපද්‍රව්‍ය' (Solid Waste) විසඳීමට පළමු පියවර කුමක්ද?", "නිවසේදීම දිරන කසළ, ප්ලාස්ටික්, වීදුරු හා කඩදාසි ලෙස කසළ වර්ගීකරණය කිරීම", "සියලු කසළ ගංගාවලට විසි කිරීම", "කසළ පාර අයිනේ පිළිස්සීම", "ප්ලාස්ටික් භාවිතය දස ගුණයකින් වැඩි කිරීම", "මූලාශ්‍රයේදීම කසළ වෙන් කිරීමෙන් කොම්පෝස්ට් පොහොර සෑදීම හා ප්‍රතිචක්‍රීකරණය පහසු වේ."),
    q("පරිසරයට එකතු වන තනි භාවිත ප්ලාස්ටික් (Single-use Plastics) සියවස් ගණනාවක් දිරාපත් නොවී පැවතීමෙන් ඇතිවන හානිය කුමක්ද?", "ජල මාර්ග අවහිර වී ගංවතුර ඇති වීම, සාගර ජීවීන් මිය යාම හා පස නිසරු වීම", "පසෙහි සාරවත් බව වැඩි වීම", "වර්ෂාපතනය නිසි කලට ලැබීම", "මත්ස්‍ය සම්පත දෙගුණ වීම", "රෙදි බෑග් හා නැවත පිරවිය හැකි බෝතල් භාවිතය මඟින් ප්ලාස්ටික් දූෂණය අවම කළ හැක."),
    q("වනාන්තර හෙළි පෙහෙළි කිරීම (Deforestation) නිසා මධ්‍යම කඳුකරයේ සිදුවන බරපතළම ස්වභාවික ආපදා දෙක මොනවාද?", "නායයෑම් ඉහළ යාම සහ ජල උල්පත් සිඳී යාම", "හිම කුණාටු ඇති වීම", "ගිනිකඳු පිපිරීම", "සුනාමි රළ ඇති වීම", "ගස් මුල් මඟින් පස රඳවා ගැනීම හා වැසි ජලය පොළොවට උරා ගැනීම නැතිවීමෙන් මෙම ආපදා හටගනී."),
    q("ස්වභාවික ආපදා කළමනාකරණ චක්‍රයේ 'ආපදාවකට පෙර' අවධියේදී සිදු කළ යුතු ප්‍රධාන කාර්යයන් මොනවාද?", "අවදානම් සිතියම් සෑදීම, පූර්ව අනතුරු ඇඟවීමේ පද්ධති සවි කිරීම සහ පෙරහුරු පැවැත්වීම", "ආපදාව වන තුරු බලා සිටීම", "ආධාර මුදල් අවභාවිත කිරීම", "රෝහල් වසා දැමීම", "සූදානම් වීම (Preparedness) හා අවම කිරීම (Mitigation) මඟින් ජීවිත හානි බොහෝ දුරට වළක්වා ගත හැක."),
    q("සුනාමි හෝ ගංවතුර වැනි ආපදාවක් සිදු වූ වහාම 'ප්‍රතිචාර දැක්වීමේ' (Response) අවධියේදී ප්‍රමුඛත්වය දිය යුත්තේ කුමකටද?", "විපතට පත් ජනතාවගේ ජීවිත බේරා ගැනීම, ප්‍රථමාධාර, ආහාර, පිරිසිදු ජලය හා ආරක්ෂිත ස්ථාන සැපයීම", "නව පාසල් විභාග කාලසටහන් හැදීම", "වෙළඳසැල්වල බදු වැඩි කිරීම", "මාර්ග තාර දැමීම", "ආපදාව සිදුවන අවස්ථාවේ ජීවිතාරක්ෂාව හා හදිසි මානුෂීය සහන සැපයීම ප්‍රථම වගකීමයි."),
    q("ආපදාවකට පසුව ක්‍රියාත්මක වන 'යථා තත්ත්වයට පත් කිරීමේ' (Recovery) අවධියේදී අනුගමනය කරන 'Build Back Better' ප්‍රතිපත්තිය යනු කුමක්ද?", "විනාශ වූ නිවාස හා යටිතල පහසුකම් ඉදිරි ආපදාවලට ඔරොත්තු දෙන ලෙස වඩාත් ශක්තිමත්ව යළි ගොඩනැගීම", "ගංවතුරට යටවන තැන්වලම දුර්වල පැල්පත් තැනීම", "පාසල් නොසාදා අත්හැර දැමීම", "පූර්ව අනතුරු පද්ධති ගලවා දැමීම", "නැවත ඉදිකිරීමේදී ආපදා අවදානම් අවම කිරීමේ ප්‍රමිතීන් ඇතුළත් කිරීමෙන් අනාගත හානි වළක්වයි."),
    q("පවුල තුළ හදිසි ආපදාවකට මුහුණ දීමට සූදානම් කර තබා ගන්නා 'ආපදා සූදානම් බෑගයේ' (Emergency Kit) තිබිය යුතු දේ මොනවාද?", "හඳුනාගැනීමේ ලිපිගොනු, ප්‍රථමාධාර පෙට්ටිය, විදුලි පන්දම, වියළි ආහාර, පානීය ජලය හා අත්‍යවශ්‍ය ඖෂධ", "රූපවාහිනී යන්ත්‍ර හා ගෘහ භාණ්ඩ", "බර යකඩ ආයුධ", "විශාල පොත් රාක්ක", "හදිසි ඉවත් වීමකදී පැය 72ක් පමණ ජීවත් වීමට අවශ්‍ය අත්‍යවශ්‍ය ද්‍රව්‍ය එහි තැබිය යුතුය."),
    q("ශ්‍රී ලංකාවේ හදිසි ආපදා තත්ත්වයක් වාර්තා කිරීමට හෝ උපකාර ලබාගැනීමට ආපදා කළමනාකරණ මධ්‍යස්ථානයේ ඇමතුම් අංකය කුමක්ද?", "117", "119", "1919", "1977", "117 යනු ආපදා කළමනාකරණ මධ්‍යස්ථානයේ (DMC) පැය 24 හදිසි ඇමතුම් අංකයයි."),
    q("සංවර්ධන ව්‍යාපෘතියක් තුළින් පරිසරයට සිදුවන හානිය අවම කිරීම සඳහා පවත්වන 'පාරිසරික බලපෑම් ඇගයීමේ' (EIA) විශේෂ ප්‍රජාතන්ත්‍රවාදී පියවර කුමක්ද?", "වාර්තාව දින 30ක් මහජන අදහස් විමසීම සඳහා ප්‍රදර්ශනය කිරීම", "වාර්තාව රහසිගතව පුළුස්සා දැමීම", "අධිකරණයට ඉදිරිපත් කිරීම තහනම් කිරීම", "ව්‍යාපෘතිය අවසන් වූ පසු ලිවීම", "ප්‍රදේශයේ ජනතාවට තම පාරිසරික ගැටලු හා විරෝධතා ඉදිරිපත් කිරීමට EIA මහජන විමසීම ඉඩ දෙයි."),
    q("හරිත ආර්ථිකයක් (Green Economy) ගොඩනැගීමේදී රාජ්‍ය හා පෞද්ගලික අංශය ප්‍රමුඛත්වය දෙන ක්‍රියාකාරකම් මොනවාද?", "කාබන් විමෝචනය අඩු කිරීම, සම්පත් කාර්යක්ෂමතාව වැඩි කිරීම හා පරිසර හිතකාමී රැකියා බිහිකිරීම", "සියලු ගංගා අපවිත්‍ර කිරීම", "ගල් අඟුරු බලාගාර පමණක් තැනීම", "පරිසර නීති අහෝසි කිරීම", "පාරිසරික අවදානම අවම කරමින් ආර්ථික දියුණුව හා මානව යහපැවැත්ම ළඟා කර ගැනීම හරිත ආර්ථිකයයි."),
    q("මහජනතාව මුහුණ දෙන පාරිභෝගික භාණ්ඩවල 'කෘත්‍රිම රසකාරක හා වර්ණක' අධි භාවිතය වැළැක්වීමේදී රජයේ කාර්යභාරය කුමක්ද?", "ආහාර පනත යටතේ සෞඛ්‍ය පරීක්ෂණ සිදු කර නීති විරෝධී නිෂ්පාදකයන්ට නඩු පැවරීම", "වර්ණක ආනයනයට ත්‍යාග දීම", "මහජන සෞඛ්‍ය පරීක්ෂකවරුන් ඉවත් කිරීම", "ආහාර ලේබල් නීති අවලංගු කිරීම", "1980 අංක 26 ආහාර පනත යටතේ මහජන සෞඛ්‍ය පරීක්ෂකවරුන් (PHI) හා ආහාර පරීක්ෂකවරුන් ක්‍රියා කරයි."),
    q("සමාජ සුබසාධන ප්‍රතිලාභ ලබාදීමේදී 'මූලික අධ්‍යාපන පහසුකම් ග්‍රාමීය පාසල් දක්වා ව්‍යාප්ත කිරීමෙන්' අත්වන සමාජීය ප්‍රතිඵලය කුමක්ද?", "නාගරික හා ග්‍රාමීය පරතරය අඩු වී සියලු දරුවන්ට සමාන අධ්‍යාපන අවස්ථා හිමිවීම", "ග්‍රාමීය දරුවන් පාසල් යාම නැවැත්වීම", "නගරවල ජනගහන තදබදය දෙගුණ වීම", "සාක්ෂරතාව අඩු වීම", "දුර බැහැර ප්‍රදේශවල ගුණාත්මක අධ්‍යාපනය සමාජ සචලතාව හා දරිද්‍රතාව අඩු කිරීමට ඉවහල් වේ."),
    q("රටක සංවර්ධන සැලසුම් සැකසීමේදී 'ස්ත්‍රී පුරුෂ සමාජභාවී අයවැයකරණය' (Gender-responsive Budgeting) මඟින් බලාපොරොත්තු වන්නේ කුමක්ද?", "රාජ්‍ය වියදම් වෙන් කිරීමේදී කාන්තාවන්ගේ හා පුරුෂයන්ගේ විශේෂිත අවශ්‍යතා සාධාරණව සැලකිල්ලට ගැනීම", "කාන්තාවන්ට බදු වැඩි කිරීම", "පිරිමින්ට රැකියා තහනම් කිරීම", "වැටුප් ලේඛන රහසිගත කිරීම", "මාතෘ සෞඛ්‍ය, ආරක්ෂාව හා කාන්තා ව්‍යවසායකත්වය සඳහා සාධාරණ අරමුදල් වෙන් කිරීම ඉන් තහවුරු වේ."),
    q("ජාතික ආදායම සමාජයේ සියලු ස්තර අතර සාධාරණව බෙදී යන ආකාරය මැනීමට ආර්ථික විද්‍යාවේ භාවිත කරන දර්ශකය කුමක්ද?", "ගිනි සංගුණකය (Gini Coefficient)", "රික්ටර් පරිමාණය", "භූමි පරිමාණය", "රේගු බදු ලේඛනය", "ආදායම් බෙදී යාමේ අසමානතාව 0 (සම්පූර්ණ සමානතාව) සිට 1 (සම්පූර්ණ අසමානතාව) දක්වා ඉන් මැනේ."),
    q("වෙළඳපොළේදී 'නියමිත ප්‍රමිතියෙන් තොර හෝ හානිකර භාණ්ඩයක්' මිලදී ගැනීමෙන් අනතුරක් සිදු වුවහොත් පාරිභෝගිකයාට ඉල්ලා සිටිය හැකි අයිතිය කුමක්ද?", "හානිය සඳහා සාධාරණ වන්දි හා නීතිමය පිළිසරණ ලැබීමේ අයිතිය (Right to Redress)", "භාණ්ඩය නිහඬව විසි කිරීම", "වෙළෙන්දාට ප්‍රශංසා කිරීම", "අමතර බද්දක් ගෙවීම", "පාරිභෝගික අධිකාරි පනත යටතේ වන්දි ලබාගැනීමට හා නීතිමය පියවර ගැනීමට පාරිභෝගිකයාට හිමිකම ඇත."),
    q("බහුසංස්කෘතික සමාජයක විවිධ ආගමික හා ජාතික ප්‍රජාවන් අතර සුහදතාව වැඩි කිරීමට පිහිටුවා ඇති ප්‍රජා කමිටු කවරේද?", "ප්‍රජා සංහිඳියා හා සාම කමිටු", "ප්‍රාදේශීය ඒකාධිකාර කමිටු", "වාර්ගික වෙන්කිරීමේ සභා", "වාරණ මණ්ඩල", "ගැටුම් පූර්වයේදීම හඳුනාගෙන සංවාදයෙන් විසඳීමට සර්ව ආගමික හා ප්‍රජා සාම කමිටු ක්‍රියා කරයි."),
    q("ශ්‍රී ලංකාවේ 'ජෛව විවිධත්වය' (Biodiversity) සංරක්ෂණය කිරීම ආර්ථිකමය වශයෙන්ද වැදගත් වන්නේ ඇයි?", "පරිසර සංචාරක ව්‍යාපාරය, ඖෂධීය ශාක හා කෘෂිකාර්මික පරාගණය රඳා පවතින්නේ ඒ මත බැවිනි", "වනාන්තර කපා දර විකිණීමට හැකි බැවිනි", "කෘමීන් සියල්ල විනාශ කිරීමට", "ජල විදුලි බලාගාර වැසීමට", "ශ්‍රී ලංකාව ලොව ප්‍රධාන ජෛව විවිධත්ව කලාපයක් (Biodiversity Hotspot) වන අතර එය රටේ ධනයකි."),
    q("සංවර්ධනය වන නගරවල 'හරිත ගොඩනැගිලි' (Green Buildings) ඉදිකිරීමෙන් අපේක්ෂා කරන්නේ කුමක්ද?", "ස්වාභාවික ආලෝකය, වැසි ජල රැස් කිරීම හා අඩු බලශක්ති පරිභෝජනයෙන් පරිසර හිතකාමී පැවැත්ම", "විදුලි පරිභෝජනය තුන් ගුණයකින් වැඩි කිරීම", "කොළ පැහැති තීන්ත ආලේප කිරීම පමණි", "ගස් කපා කොන්ක්‍රීට් පමණක් දැමීම", "බලශක්ති හා ජල කාර්යක්ෂමතාව ඉහළ නංවා කාබන් පියසටහන අඩු කිරීම හරිත ඉදිකිරීම්වල අරමුණයි."),
    q("ගෝලීය උණුසුම ඉහළ යාම හේතුවෙන් ශ්‍රී ලංකාව වැනි දූපත් රාජ්‍යයකට මුහුණ දීමට සිදුවන ප්‍රධාන තර්ජනයක් කුමක්ද?", "මුහුදු මට්ටම ඉහළ යාමෙන් වෙරළබඩ ප්‍රදේශ ඛාදනය වීම හා ජල මූලාශ්‍රවලට ලුණු ජලය මුසු වීම", "සෑම මාසයකම හිම පතනය වීම", "සාගරය සම්පූර්ණයෙන් සිඳී යාම", "රට තුළ නව ගිනිකඳු මතුවීම", "දේශගුණික විපර්යාස අනුවර්තනය දූපත් රාජ්‍යයන්ගේ ආහාර සුරක්ෂිතතාව හා වෙරළ ආරක්ෂාවට අත්‍යවශ්‍යය."),
    q("පාරිභෝගිකයන් වශයෙන් 'ලේබල් නොකළ හෝ කල් ඉකුත් වූ' ආහාර වෙළඳසැලක තිබෙනු දුටු විට ගත යුතු වගකිවයුතු පියවර කුමක්ද?", "ඒවා මිලදී නොගෙන ප්‍රාදේශීය මහජන සෞඛ්‍ය පරීක්ෂක (PHI) හෝ පාරිභෝගික අධිකාරියට දැනුම් දීම", "මිල අඩු බැවින් මිලදී ගෙන ආහාරයට ගැනීම", "වෙළෙන්දාට අමතර මුදලක් ගෙවීම", "නිහඬව පිටවී යාම", "අනෙක් පාරිභෝගිකයන්ගේ සෞඛ්‍ය ආරක්ෂාව වෙනුවෙන්ද වැරදි පෙන්වා දීම පුරවැසි වගකීමකි."),
    q("රටේ සංවර්ධනය සඳහා 'කුඩා හා මධ්‍ය පරිමාණ ව්‍යවසායන්' (SMEs) දිරිගැන්වීම වැදගත් වන්නේ ඇයි?", "ග්‍රාමීය හා ප්‍රාදේශීය රැකියා අවස්ථා බිහි කර දේශීය අමුද්‍රව්‍යවලට අගය එකතු කරන බැවිනි", "විදේශීය ආනයන සම්පූර්ණයෙන් වැසීමට", "බදු ආදායම නැති කිරීමට", "විශාල ඒකාධිකාර බිහිකිරීමට", "SME අංශය ඕනෑම ආර්ථිකයක කොඳු නාරටිය ලෙස සැලකෙන අතර ආදායම් බෙදී යාම පුළුල් කරයි."),
    q("වෙළඳපොළේදී 'විකුණා අවසන් කළ භාණ්ඩ ආපසු භාර නොගැනේ' (No Refund / No Exchange) යනුවෙන් දෝෂ සහිත භාණ්ඩ සඳහා පුවරු ගැසීම නීත්‍යානුකූලද?", "නැත, දෝෂ සහිත හෝ අනාරක්ෂිත භාණ්ඩ සඳහා වගකීම පැහැර හැරීම පාරිභෝගික නීතියට පටහැනිය", "ඔව්, වෙළෙන්දාට සම්පූර්ණ බලය ඇත", "ඔව්, කල් ඉකුත් වූ භාණ්ඩවලටද වලංගුය", "ඔව්, එය ව්‍යවස්ථාමය අයිතියකි", "වලංගු බිල්පතක් ඇති විට නිෂ්පාදන දෝෂ සඳහා ආපසු දීමේ හා වගකීමේ අයිතිය පාරිභෝගිකයාට හිමිවේ."),
    q("රජයේ සුබසාධන සේවාවන්ට අමතරව දරුවන්, වැඩිහිටියන් හා ආබාධිත පුද්ගලයන් රැකබලා ගැනීමට සමාජය තුළ තිබිය යුතු ගුණාංගය කුමක්ද?", "සමාජ සහයෝගීතාව, සහකම්පනය හා ඇතුළත් කරගැනීම (Social Inclusion)", "සමාජයෙන් කොන් කිරීම", "ආර්ථික තරගය පමණක්", "නීති විරෝධී ශ්‍රමය", "ආබාධ සහිත පුද්ගලයන්ටද ප්‍රවේශ පහසුකම් හා සමාන අවස්ථා සැලසීම ශිෂ්ට සම්පන්න සමාජයක ලක්ෂණයකි."),
    q("ශ්‍රී ලංකාවේ තිරසාර ජල කළමනාකරණයට පුරාණ රජවරුන් විසින් ගොඩනගන ලද 'එල්ලංගා වැව් පද්ධති' (Tank Cascade System) උපකාරී වන්නේ කෙසේද?", "වැසි ජලය රැස් කරමින් පහළ වැව්වලට ක්‍රමයෙන් ගලා යාමට සලස්වා භූගත ජලය හා ජෛව විවිධත්වය රැකීමෙන්", "සියලු ජලය මුහුදට ඉක්මනින් යැවීමෙන්", "වගාවන් සම්පූර්ණයෙන් නැවැත්වීමෙන්", "රසායනික කර්මාන්තශාලා ඉදිකිරීමෙන්", "FAO ආයතනය මඟින් පවා ශ්‍රී ලංකාවේ එල්ලංගා වැව් පද්ධතිය ගෝලීය කෘෂිකාර්මික උරුමයක් ලෙස පිළිගෙන ඇත."),
    q("වෙළඳපොළ ආර්ථික ක්‍රමයේදී මිල ඉහළ යාම පාලනය කිරීමට රජය 'ආනයන බදු අඩු කිරීම' වැනි පියවරක් ගන්නේ කුමන අවස්ථාවකදීද?", "අත්‍යවශ්‍ය ආහාර ද්‍රව්‍යවල දේශීය හිඟයක් හා අධික මිල ඉහළ යාමක් ඇති වූ විට", "දේශීය අස්වැන්න අතිරික්තයක් ඇති විට", "පරිභෝජනය සම්පූර්ණයෙන් නතර කිරීමට", "අපනයන ආදායම අඩු කිරීමට", "මිශ්‍ර ආර්ථිකයක වෙළඳපොළ ස්ථාවර කිරීමට රජය බදු ප්‍රතිපත්ති උපකරණ ලෙස භාවිත කරයි."),
    q("පුරවැසියන්ට 'රැකියා විරහිත බව' (Unemployment) අවම කිරීම සඳහා අධ්‍යාපන පද්ධතියේ සිදු කළ යුතු ප්‍රධාන වෙනස කුමක්ද?", "වෙළඳපොළ ඉල්ලුමට ගැළපෙන වෘත්තීය පුහුණුව, තාක්ෂණික කුසලතා හා ව්‍යවසායකත්ව අධ්‍යාපනය දියුණු කිරීම", "ප්‍රායෝගික විෂයන් ඉවත් කිරීම", "පාසල් වසර ගණන අඩු කිරීම", "පරිගණක අධ්‍යාපනය තහනම් කිරීම", "රැකියා ලෝකයට අවශ්‍ය කුසලතා සංවර්ධනයෙන් රැකියා නියුක්තිය හා ජාතික නිෂ්පාදනය ඉහළ යයි."),
    q("බහුසංස්කෘතික සමාජයක සාමය රැකීමට 'වෛරී ප්‍රකාශ' (Hate Speech) පාලනය කිරීම වැදගත් වන්නේ ඇයි?", "විවිධ ජන කොටස් හෝ ආගම් අතර ප්‍රචණ්ඩත්වය හා වෙනස් කොට සැලකීම ඇවිලවීම වැළැක්වීමට", "අදහස් ප්‍රකාශ කිරීම සම්පූර්ණයෙන් තහනම් කිරීමට", "සමාජ මාධ්‍ය වසා දැමීමට", "විදේශ සංචාරකයන් නැවැත්වීමට", "2007 අංක 56 ICCPR පනත මඟින් ජාතික හා ආගමික වෛරය පැතිරවීම නීතියෙන් තහනම් කර ඇත."),
    q("පරිසරයට හා සමාජයට වගකිවයුතු 'ව්‍යාපාරික ආයතනයක්' සමාජ සුබසාධනය උදෙසා සිදු කරන ස්වේච්ඡා කටයුතු හඳුන්වන්නේ කෙසේද?", "සංගත සමාජ වගකීම (Corporate Social Responsibility - CSR)", "කළුකඩ වෙළඳාම", "බදු පැහැර හැරීම", "වෙළඳ ඒකාධිකාරය", "පාසල්වලට පුස්තකාල තැනීම, රුක් රෝපණය හා පාරිසරික සංරක්ෂණය වැනි CSR ව්‍යාපෘති සමාජයට සේවය කරයි."),
    q("රටේ සියලු පුරවැසියන්ට ආර්ථික සංවර්ධනයේ ප්‍රතිලාභ සමානව බෙදී යන සංවර්ධන ප්‍රවේශය හඳුන්වන්නේ කුමන නමින්ද?", "ඇතුළත් කරගත් සංවර්ධනය (Inclusive Growth)", "ඒකපාක්ෂික සංවර්ධනය", "නාගරික කේන්ද්‍රීය වර්ධනය පමණක්", "පෞද්ගලික ඒකාධිකාර වර්ධනය", "ග්‍රාමීය ප්‍රජාව, කාන්තාවන්, තරුණයන් හා ආබාධිත ප්‍රජාවද ආර්ථික ක්‍රියාවලියට දායක කර ගැනීම මෙයයි."),
    q("පාරිසරික ආරක්ෂණය සඳහා 'කාබන් පියසටහන' (Carbon Footprint) අඩු කිරීම යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "පුද්ගලයෙකුගේ හෝ ආයතනයක ක්‍රියාකාරකම් මඟින් වායුගෝලයට මුදාහරින හරිතාගාර වායු ප්‍රමාණය අවම කිරීම", "පාවහන් නිෂ්පාදනය නැවැත්වීම", "වනාන්තරවල ගමන් කිරීම තහනම් කිරීම", "සියලු ගොවිතැන් නැවැත්වීම", "බලශක්ති ඉතිරිය, දේශීය ආහාර පරිභෝජනය හා පොදු ප්‍රවාහනය කාබන් පියසටහන අඩු කරයි."),
    q("සුබසාධක රාජ්‍යයක 'සමාජ ආරක්ෂණ ජාලය' (Social Safety Net) මඟින් ආවරණය කරන්නේ කවුරුන්ද?", "වැඩිහිටියන්, අනාථ දරුවන්, ආබාධිතයන් හා හදිසි විපත්වලට මුහුණ දුන් අසරණ පුද්ගලයන්", "බහුජාතික සමාගම් හිමිකරුවන්", "විදේශීය සංචාරකයන් පමණි", "රාජ්‍ය ඇමතිවරුන් පමණි", "ආර්ථික කම්පන හා ජීවිත අවදානම් හමුවේ කිසිවෙකු අසරණ නොවී රැකගැනීම සමාජ ආරක්ෂණ ජාලයේ කාර්යයයි."),
    q("ශ්‍රී ලංකාවේ රාජ්‍ය බදු ප්‍රතිපත්තිය සැකසීමේදී 'බදු පදනම පුළුල් කිරීම' (Widening the Tax Base) යනු කුමක්ද?", "බදු ගෙවීමේ හැකියාව ඇති සියලු දෙනා හා අංශ බදු දැලට ඇතුළත් කර සාධාරණ ලෙස බදු රැස් කිරීම", "සෑම දිළිඳු පවුලකටම නව බදු ගැසීම", "සියලු ආදායම් බදු ඉවත් කිරීම", "රේගුව වසා දැමීම", "බදු පැහැර හැරීම් නවතා සියලු සුදුසුකම් ලත් අය බදු ගෙවන විට රාජ්‍ය ආදායම ස්ථාවර වේ."),
    q("වෙළඳපොළේ පාරිභෝගිකයන් වෙත 'අන්තර්ජාලය හරහා භාණ්ඩ අලෙවි කිරීමේදී' (E-commerce) ප්‍රධාන වශයෙන් රැකගත යුත්තේ කුමක්ද?", "භාණ්ඩයේ සැබෑ විස්තර නිවැරදිව දැක්වීම හා පාරිභෝගික දත්ත හා ගෙවීම් ආරක්ෂාව", "ව්‍යාජ ඡායාරූප පළ කිරීම", "වෙනත් අයගේ ක්‍රෙඩිට් කාඩ් දත්ත විකිණීම", "බිල්පත් නොදී සිටීම", "ඩිජිටල් ආර්ථිකය වර්ධනය වන විට මාර්ගගත පාරිභෝගික ආරක්ෂාව අත්‍යවශ්‍ය අංගයක් වී ඇත."),
    q("ශ්‍රී ලංකාවේ තේ, රබර් හා පොල් වැනි සාම්ප්‍රදායික අපනයනවලට අමතරව ආර්ථික වර්ධනයට වැදගත් වන නව අපනයන අංශයක් කුමක්ද?", "තොරතුරු තාක්ෂණ සේවා (IT/BPM) සහ අගය එකතු කළ කුළුබඩු නිෂ්පාදන", "ගල් අඟුරු අපනයනය", "ඛනිජ තෙල් අපනයනය", "අමු වැලි අපනයනය", "දැනුම පදනම් කරගත් ආර්ථිකයක IT සේවා අපනයනය ඉහළ විදේශ විනිමය උපයා දෙයි."),
    q("තිරසාර සංවර්ධනයේදී 'ග්‍රාමීය සංවර්ධනය' (Rural Development) ප්‍රමුඛ වන්නේ ඇයි?", "රටේ බහුතර ජනගහනය ජීවත් වන ග්‍රාමීය අංශයේ ජීවන තත්ත්වය නැංවීමෙන් සමස්ත රටම දියුණු වන බැවිනි", "ගම්මාන සියල්ල වසා දැමීමට", "කෘෂිකර්මාන්තය සම්පූර්ණයෙන් නැවැත්වීමට", "ග්‍රාමීය පාසල් ඉවත් කිරීමට", "මාර්ග, විදුලිය, අන්තර්ජාලය හා වෙළඳපොළ පහසුකම් ගමට ලැබෙන විට නාගරික තදබදයද අඩුවේ."),
    q("පරිසරයට හානි කරන ඝෝෂාකාරී කර්මාන්තශාලා ජනාවාස ප්‍රදේශවලින් ඈත්ව පිහිටුවීම සඳහා රජය භාවිත කරන ක්‍රමවේදය කුමක්ද?", "කලාපකරණය (Zoning) සහ කාර්මික උද්‍යාන පිහිටුවීම", "ජනාවාස මැද ශබ්ද විකාශන යන්ත්‍ර සවි කිරීම", "පරිසර බලපත්‍ර නැවැත්වීම", "පාසල් අසල අපද්‍රව්‍ය දැමීම", "නාගරික හා ප්‍රාදේශීය සැලසුම්කරණයේදී කර්මාන්ත කලාප හා නේවාසික කලාප වෙන් කිරීම වැදගත්ය."),
    q("බහුසංස්කෘතික සමාජයක 'සමාන අවස්ථා ප්‍රතිපත්තිය' (Equal Opportunity Policy) රැකියා ස්ථානයක ක්‍රියාත්මක වන්නේ කෙසේද?", "ජාතිය, ආගම, ස්ත්‍රී පුරුෂ භාවය නොසලකා සුදුසුකම් හා දක්ෂතාව මත පමණක් බඳවා ගැනීම් කිරීමෙන්", "ඥාති සංග්‍රහය මත පමණක් පත්වීම් දීමෙන්", "සුළුතර ජන කොටස් ප්‍රතික්ෂේප කිරීමෙන්", "කාන්තාවන්ට අඩු වැටුප් ගෙවීමෙන්", "විවිධත්වයෙන් යුත් කාර්ය මණ්ඩලයක් සමානව සැලකීමෙන් ආයතනික ඵලදායීතාව හා සමාජ සාධාරණත්වය වැඩි වේ."),
    q("ජාතික ආර්ථිකයක 'ඉතිරි කිරීම් හා ආයෝජන' (Savings and Investment) අතර පවතින සම්බන්ධතාව කුමක්ද?", "ජනතාවගේ ඉතිරි කිරීම් බැංකු හරහා නව කර්මාන්ත හා ව්‍යාපාර සඳහා ආයෝජන ප්‍රාග්ධනය බවට පත් වේ", "ඉතිරි කිරීම නිසා ආයෝජන නතර වේ", "බැංකු වසා දැමීමෙන් ආයෝජන වැඩි වේ", "මුදල් ඉතිරි කිරීම නීති විරෝධීය", "ප්‍රාග්ධන සම්පාදනය ඉහළ යාමෙන් රටේ නිෂ්පාදන ධාරිතාව හා රැකියා උත්පාදනය වර්ධනය වේ."),
    q("වෙළඳපොළේ පාරිභෝගිකයන් හට 'මිල ගණන් ප්‍රදර්ශනය කිරීම' (Price Display) අනිවාර්ය කර ඇත්තේ ඇයි?", "පාරිභෝගිකයන්ට මිල සංසන්දනය කර සාධාරණ තීරණ ගැනීමට හා වැඩි මිලට විකිණීම වැළැක්වීමට", "වෙළෙන්දාට කැමති මිලක් රහසේ අය කිරීමට", "භාණ්ඩ සඟවා තැබීමට", "බිල්පත් නොදීමට", "සෑම භාණ්ඩයකම පැහැදිලි මිල ප්‍රදර්ශනය පාරිභෝගික අධිකාරි රෙගුලාසි අනුව නීතිමය අවශ්‍යතාවකි."),
    q("සුබසාධක සේවා ක්‍රියාත්මක කිරීමේදී රජය මුහුණ දෙන ප්‍රධානතම මූල්‍ය අභියෝගය කුමක්ද?", "සීමිත රාජ්‍ය ආදායම තුළ සුබසාධන වියදම් හා ආර්ථික සංවර්ධන ආයෝජන සමබරව පවත්වාගැනීම", "සියලුම පාසල් වැසී යාම", "බදු ගෙවන්නන් වැඩි වීම", "විදේශ සංචිත අසීමිත වීම", "දිගුකාලීන ආර්ථික වර්ධනයට බාධා නොවන පරිදි කාර්යක්ෂමව සුබසාධනය කළමනාකරණය කළ යුතුය."),
    q("ශ්‍රී ලංකාවේ 'වනජීවී හා වෘක්ෂලතා ආරක්ෂණ ආඥාපනත' යටතේ වඳවී යාමේ තර්ජනයට ලක් වූ ශාක හා සතුන් රැකගන්නේ කෙසේද?", "ජාතික වනෝද්‍යාන, අභයභූමි හා දැඩි ස්වභාවික රක්ෂිත ප්‍රකාශයට පත් කර දඩයම් තහනම් කිරීමෙන්", "සතුන් සියල්ල විදෙස් රටවලට විකිණීමෙන්", "රක්ෂිත තුළ කර්මාන්තශාලා තැනීමෙන්", "වනාන්තර ගිනි තැබීමෙන්", "වනජීවී සංරක්ෂණ දෙපාර්තමේන්තුව මෙම රක්ෂිත කලාප ආරක්ෂා කිරීමට නීතිය ක්‍රියාත්මක කරයි."),
    q("නාගරික වායු දූෂණය අවම කර තිරසාර ප්‍රවාහනය ප්‍රවර්ධනය කිරීමට රජය ගත හැකි හොඳම පියවර කුමක්ද?", "විශ්වසනීය හා පිරිසිදු පොදු ප්‍රවාහන සේවා (දුම්රිය හා බස්) සහ විදුලි වාහන දිරිගැන්වීම", "පැරණි ඩීසල් වාහන ප්‍රමාණය දස ගුණයකින් වැඩි කිරීම", "දුම්රිය මාර්ග ගලවා දැමීම", "වාහන දුම් පරීක්ෂණ නතර කිරීම", "පෞද්ගලික මෝටර් රථ භාවිතය අඩු වන විට ඉන්ධන දහනය හා මාර්ග තදබදය පහළ බසී."),
    q("බහුසංස්කෘතික සමාජයක විවිධ ප්‍රජාවන්ගේ 'ආහාර, සංගීතය හා කලා ශිල්ප' හුවමාරු වීමෙන් සමාජයට අත්වන වාසිය කුමක්ද?", "සංස්කෘතික පොහොසත්කම, නිර්මාණශීලීත්වය හා ප්‍රජාවන් අතර සුහද බැඳීම් වර්ධනය වීම", "සංස්කෘතීන් සම්පූර්ණයෙන් විනාශ වීම", "කලා නිර්මාණ තහනම් වීම", "වාර්ගික ආතතිය ඉහළ යාම", "සංස්කෘතික විවිධත්වය සංචාරක ආකර්ෂණයටද ජාතික එකමුතුකමටද ආශිර්වාදයකි."),
    q("ආර්ථික අර්බුදයකින් රටක් ගොඩඒමට නම් 'නිෂ්පාදන ආර්ථිකයක්' ගොඩනැගීම වැදගත් වන්නේ ඇයි?", "ආනයන මත යැපීම අඩු කර අපනයන ආදායම් වැඩි කිරීමෙන් විදේශ විනිමය ස්ථාවර වන බැවිනි", "භාණ්ඩ නිපදවීම සම්පූර්ණයෙන් නතර කිරීමට", "සියලු දේ විදේශයෙන් ණයට ගැනීමට", "කර්මාන්තශාලා වසා දැමීමට", "දේශීය කෘෂිකර්මය හා කර්මාන්ත ශක්තිමත් කිරීමෙන් තිරසාර ආර්ථික ස්වාධීනත්වයක් ලැබේ."),
    q("ශ්‍රී ලංකාවේ 'තැපැල් හා මූල්‍ය සේවා' හරහා ග්‍රාමීය ජනතාවට බැංකු පහසුකම් ලබාදීම හඳුන්වන්නේ කුමන සංකල්පයෙන්ද?", "මූල්‍ය ඇතුළත් කිරීම (Financial Inclusion)", "මූල්‍ය ඒකාධිකාරය", "උද්ධමන ඉලක්කකරණය", "කළුකඩ ආර්ථිකය", "සෑම පුරවැසියෙකුටම ආරක්ෂිත බැංකු ගිණුම්, ඉතුරුම් හා සාධාරණ ණය පහසුකම් සැලසීම මෙයයි."),
    q("තිරසාර සංවර්ධනය සඳහා 'කෘෂිකාර්මික ජල කළමනාකරණයේදී' බිංදු ජල සම්පාදනය (Drip Irrigation) යොදාගැනීමේ වාසිය කුමක්ද?", "ජල නාස්තිය අවම කරමින් බෝගවල මුල් පද්ධතියට අවශ්‍ය ජලය පමණක් කාර්යක්ෂමව සැපයීම", "විශාල ජල ප්‍රමාණයක් අපතේ යැවීම", "පස සෝදාපාළු කිරීම", "වියළි කලාපයේ වගාව නැවැත්වීම", "ජල හිඟය පවතින ප්‍රදේශවල තිරසාර ආහාර නිෂ්පාදනයට නවීන වාරි තාක්ෂණය අත්‍යවශ්‍යය."),
    q("වෙළඳපොළේදී පාරිභෝගිකයෙකු ඖෂධ මිලදී ගැනීමේදී පිළිපැදිය යුතු ප්‍රධාන ආරක්ෂණ පිළිවෙත කුමක්ද?", "සුදුසුකම් ලත් වෛද්‍ය නිර්දේශය මත ලියාපදිංචි ඔසුසලකින් කල් ඉකුත් නොවූ ඖෂධ ගැනීම", "පදික වේදිකාවෙන් ලිපිගොනු නොමැතිව ගැනීම", "කල් ඉකුත් වූ දිනය නොබලා භාවිත කිරීම", "වෙනත් රෝගියෙකුගේ ඖෂධ පාවිච්චි කිරීම", "ජාතික ඖෂධ නියාමන අධිකාරිය (NMRA) රටේ ඖෂධවල ගුණාත්මක බව හා මිල නියාමනය කරයි."),
    q("සමාජ සුබසාධනයේදී 'නිදහස් අධ්‍යාපනයේ ප්‍රධාන අරමුණු' අතරට නොගැනෙන්නේ කුමක්ද?", "ධනවත් පවුල්වල දරුවන්ට පමණක් විශ්වවිද්‍යාල වරම් සීමා කිරීම", "සමාජ ආර්ථික බාධක නොතකා දක්ෂතාවයට අනුව ඉදිරියට යාමට ඉඩ දීම", "සාක්ෂරතාව හා දැනුම ඉහළ නැංවීම", "සමාජ සමානාත්මතාව ඇති කිරීම", "නිදහස් අධ්‍යාපනය සියලු පුරවැසියන්ට සමාන අවස්ථා සලසන ප්‍රජාතන්ත්‍රවාදී අයිතිවාසිකමකි."),
    q("ශ්‍රී ලංකාවේ 'ගංගා නිම්න හා වෙරළ තීරයන්හි අනවසර වැලි හා ගල් කැණීම්' තහනම් කර ඇත්තේ ඇයි?", "ගං ඉවුරු ඛාදනය, පාලම් කඩා වැටීම, ලුණු ජලය ඇතුළු වීම හා පරිසර පද්ධති විනාශය වැළැක්වීමට", "ඉදිකිරීම් සම්පූර්ණයෙන් නැවැත්වීමට", "මත්ස්‍යයන් අඩු කිරීමට", "ගංවතුර වැඩි කිරීමට", "භූ විද්‍යා සමීක්ෂණ හා පතල් කාර්යාංශය (GSMB) බලපත්‍ර ක්‍රමය මඟින් කැණීම් පාලනය කරයි."),
    q("බහුසංස්කෘතික සමාජයක 'ජාතික උත්සව හා ස්මාරක' සංරක්ෂණය කිරීමේදී පිළිබිඹු කළ යුත්තේ කුමක්ද?", "රටේ සියලු ජන කොටස්වල ඓතිහාසික දායකත්වය හා සංස්කෘතික උරුමය ගෞරවයෙන් පිළිගැනීම", "එක් කණ්ඩායමක ඉතිහාසය පමණක් මකා දැමීම", "පුරාවිද්‍යා ස්ථාන විනාශ කිරීම", "සංචාරකයන්ට ඇතුළු වීම තහනම් කිරීම", "සියලු ප්‍රජාවන්ගේ උරුමය රැකගැනීම ජාතික අභිමානය හා සංහිඳියාව වර්ධනය කරයි."),
    q("තිරසාර සංවර්ධන ඉලක්ක (SDGs) අතුරින් 'සාගර හා සමුද්‍ර සම්පත් සංරක්ෂණය' (Life Below Water - SDG 14) වැදගත් වන්නේ ඇයි?", "කොරල්පර, මත්ස්‍ය සම්පත හා සාගර පරිසර පද්ධති ආරක්ෂා කර ආහාර සුරක්ෂිතතාව රැකීමට", "සාගරයට ප්ලාස්ටික් හා රසායනික අපද්‍රව්‍ය බැහැර කිරීමට", "තහනම් දැල් යොදා සියලු මත්ස්‍ය පැටවුන් ඇල්ලීමට", "තෙල් නැව් අනතුරු වැඩි කිරීමට", "දූපත් රාජ්‍යයක් වන ශ්‍රී ලංකාවේ ධීවර කර්මාන්තය හා සමුද්‍ර ජෛව විවිධත්වය සුරැකීම අත්‍යවශ්‍යය."),
    q("SDGs 15 වන ඉලක්කය වන 'ගොඩබිම ජීවය' (Life on Land) මඟින් ප්‍රවර්ධනය කරනු ලබන්නේ කුමක්ද?", "වනාන්තර තිරසාර ලෙස කළමනාකරණය කිරීම, කාන්තාරකරණය නැවැත්වීම හා ජෛව විවිධත්වය රැකීම", "සියලු වගුරු බිම් ගොඩකිරීම", "වන සතුන් දඩයම් කිරීම", "පස නිසරු කිරීම", "ගොඩබිම් පරිසර පද්ධති සුරැකීම මිනිසාගේ පැවැත්මට සෘජුවම බලපායි."),
    q("වෙළඳපොළ ආර්ථික ක්‍රමයේ 'විදේශ සෘජු ආයෝජන' (FDI) රටකට ආකර්ෂණය වීමෙන් ලැබෙන වාසිය කුමක්ද?", "නව ප්‍රාග්ධනය, නවීන තාක්ෂණය, රැකියා අවස්ථා හා අපනයන වෙළඳපොළ ප්‍රවේශය හිමිවීම", "රටේ සියලු විදුලි බලාගාර වැසී යාම", "ජනතාවට රැකියා අහිමි වීම", "අධ්‍යාපන ක්‍රමය නතර වීම", "විදේශ ණය බර වැඩි නොකර ආර්ථික වර්ධනය වේගවත් කිරීමට විදේශ සෘජු ආයෝජන උපකාරී වේ."),
    q("රටේ පාරිභෝගිකයන්ට 'බලශක්ති කාර්යක්ෂමතා ලේබලය' (Energy Efficiency Star Rating) බලා විදුලි උපකරණ ගැනීමෙන් ලැබෙන වාසිය කුමක්ද?", "අඩු විදුලි පරිභෝජනයක් නිසා විදුලි බිල අඩු වී පරිසර දූෂණයද අවම වීම", "විදුලි බිල දෙගුණ වීම", "උපකරණය ඉක්මනින් කැඩී යාම", "බලශක්ති නාස්තිය වැඩි වීම", "ඉහළ තරු ශ්‍රේණිගත උපකරණ තෝරාගැනීම පුද්ගලික ආර්ථිකයටත් ජාතික බලශක්ති පද්ධතියටත් හිතකරය."),
    q("ශ්‍රී ලංකාවේ 'කම්කරු හා සමාජ සුබසාධන නීති' යටතේ ළමා ශ්‍රමය (Child Labour) තහනම් කර ඇත්තේ කුමන අරමුණින්ද?", "දරුවන්ගේ අධ්‍යාපන අයිතිය, ශාරීරික සෞඛ්‍යය හා ළමා විය ආරක්ෂා කිරීමට", "ළමුන්ට අඩු වැටුපට වැඩ ගැනීමට", "පාසල් සංඛ්‍යාව අඩු කිරීමට", "ව්‍යාපාරික ලාභය වැඩි කිරීමට", "ශ්‍රී ලංකාවේ අනිවාර්ය පාසල් අධ්‍යාපන වයස හා අවම සේවා වයස අවුරුදු 16 දක්වා ඉහළ නංවා ඇත."),
    q("ආර්ථික සංවර්ධනය මනින සාම්ප්‍රදායික GDP දර්ශකයට වඩා 'හරිත දළ දේශීය නිෂ්පාදිතය' (Green GDP) වෙනස් වන්නේ කෙසේද?", "ආර්ථික නිෂ්පාදනයෙන් පරිසර දූෂණය හා ස්වභාවික සම්පත් ක්ෂය වීමේ පිරිවැය අඩු කර ගණනය කිරීමෙන්", "පරිසර විනාශය ලාභයක් ලෙස එකතු කිරීමෙන්", "කෘෂිකර්මය බින්දුවට දැමීමෙන්", "විදේශ ආදායම පමණක් ගැනීමෙන්", "සැබෑ තිරසාර සංවර්ධනයක් මැනීමේදී පාරිසරික පිරිවැයද ගිණුම්ගත කළ යුතු බව ඉන් පෙන්වා දේ."),
    q("බහුසංස්කෘතික සමාජයක පුද්ගලයෙකු අනෙක් ජනවර්ගයේ කෙනෙකු සමඟ ගනුදෙනු කිරීමේදී අනුගමනය කළ යුතු ආචාරශීලී පිළිවෙත කුමක්ද?", "සමාන ගෞරවයෙන්, විවෘත මනසින් හා කිසිදු වෙනස්කමකින් තොරව සැලකීම", "උපහාසාත්මක විහිළු කිරීම", "කණ්ඩායමෙන් කොන් කිරීම", "අවිශ්වාසයෙන් බැලීම", "පුද්ගලික ගරුත්වය ආරක්ෂා කිරීම සෑම ශිෂ්ට සමාජයකම පුරවැසි යුතුකමකි."),
    q("ස්වභාවික ආපදා වැළැක්වීම සඳහා නාගරික ප්‍රදේශවල 'තෙත් බිම් හා වගුරු බිම්' (Wetlands) ආරක්ෂා කළ යුත්තේ ඇයි?", "අධික වැසි ජලය උරා ගන්නා ස්වභාවික ස්පොන්ජියක් ලෙස ක්‍රියා කර නාගරික ගංවතුර පාලනය කරන බැවිනි", "කසළ පිරවීමට හොඳම ස්ථානය බැවිනි", "ගොඩනැගිලි ඉදිකිරීමට පමණි", "මදුරුවන් බෝ කිරීමට", "කොළඹ රැම්සා තෙත්බිම් නගරයක් ලෙස නම් කර ඇත්තේද මෙම ගංවතුර පාලන හා ජෛව විවිධත්ව වටිනාකම නිසාය."),
    q("ශ්‍රී ලංකාවේ 'ආහාර සුරක්ෂිතතාව' (Food Security) තහවුරු කිරීම සඳහා රජය හා පුරවැසියන් ගත යුතු ප්‍රධාන පියවර කුමක්ද?", "දේශීය ආහාර නිෂ්පාදනය වැඩි කිරීම, අස්වනු නාස්තිය අවම කිරීම හා ගෙවතු වගාව ප්‍රවර්ධනය කිරීම", "ගොවිබිම් සියල්ල විකුණා දැමීම", "ආහාර අපතේ යැවීම වැඩි කිරීම", "බීජ සංරක්ෂණය නතර කිරීම", "සැමට ප්‍රමාණවත් හා පෝෂ්‍යදායී ආහාර නිරන්තරයෙන් ලැබෙන බව තහවුරු කිරීම SDG 2 වන ඉලක්කයයි."),
    q("පාරිභෝගික භාණ්ඩයක ඇති 'අලෙවියෙන් පසු සේවාව හා වගකීම් සහතිකය' (Warranty) වැදගත් වන්නේ ඇයි?", "නිශ්චිත කාලයක් තුළ කාර්මික දෝෂ ඇති වුවහොත් නොමිලේ අලුත්වැඩියා කිරීම හෝ මාරු කර ගැනීමට හැකි වීමෙන්", "භාණ්ඩයේ මිල වැඩි කිරීමට", "වෙළෙන්දාට නඩු දැමීම වැළැක්වීමට", "විදුලි බිල අඩු කිරීමට", "විශේෂයෙන් විදුලි හා ඉලෙක්ට්‍රොනික උපකරණ මිලදී ගැනීමේදී ලිඛිත වගකීම් කාලය පරීක්ෂා කළ යුතුය."),
    q("රටේ සංවර්ධන ක්‍රියාවලියේදී 'තරුණ ප්‍රජාව' (Youth) සවිබල ගැන්වීම තීරණාත්මක වන්නේ ඇයි?", "තාක්ෂණික දැනුම, නවෝත්පාදන ශක්තිය හා ශ්‍රම බලකායේ ප්‍රධාන ජවය තරුණයන් සතු වන බැවිනි", "තරුණයන්ට ඡන්ද බලය නැති බැවිනි", "ඔවුන් ආර්ථිකයට දායක නොවන බැවිනි", "රැකියා අවස්ථා අඩු කිරීමට", "තරුණ ව්‍යවසායකත්වය හා කුසලතා සංවර්ධනය රටේ අනාගත ආර්ථික ප්‍රගතිය තීරණය කරයි."),
    q("ශ්‍රී ලංකාවේ 'සමුපකාර ව්‍යාපාරයේ මූලික ප්‍රතිපත්ති' අතරට අයත් වන්නේ පහත සඳහන් කුමක්ද?", "ස්වේච්ඡා හා විවෘත සාමාජිකත්වය සහ සාමාජිකයන්ගේ ප්‍රජාතන්ත්‍රවාදී පාලනය", "එක් අයෙකුට පමණක් ඡන්ද බලය සීමා කිරීම", "ලාභය පමණක් විදේශයට යැවීම", "මහජන සුබසාධනය නොසලකා හැරීම", "කොටස් ප්‍රමාණය නොතකා 'එක් සාමාජිකයෙකුට එක් ඡන්දයක්' යන්න සමුපකාර ප්‍රජාතන්ත්‍රවාදයේ මූලධර්මයයි."),
    q("තිරසාර සංවර්ධනය පිළිබඳ 'පාරිසරික පුරවැසිභාවය' (Environmental Citizenship) යනුවෙන් අදහස් කරන්නේ කුමක්ද?", "පරිසරයට හා ස්වභාවික සම්පත්වලට සිදුවන බලපෑම ගැන සිතා වගකීමෙන් ක්‍රියා කරන පුරවැසියෙකු වීම", "පරිසර නීති කඩ කිරීම", "කසළ පොදු ස්ථානවල දැමීම", "රජය පමණක් පරිසරය රැකිය යුතු යැයි සිතීම", "සොබාදහම ආරක්ෂා කිරීම 1978 ව්‍යවස්ථාවේ 28(ඊ) වගන්තිය අනුව සෑම පුරවැසියෙකුගේම මූලික යුතුකමකි."),
    q("දරිද්‍රතාව පිටුදැකීමේදී 'මූල්‍ය ආධාර පමණක් දීමට වඩා කුසලතා හා ස්වයං රැකියා උත්පාදනය' වැදගත් වන්නේ ඇයි?", "පුද්ගලයා සදාකාලික යැපුම් මානසිකත්වයෙන් මිදී ස්වාධීනව ආදායම් ඉපයීමට හැකි වන බැවිනි", "ආධාර ලබන්නන් ප්‍රමාණය වැඩි කිරීමට", "රජයේ බදු අඩු කිරීමට", "බැංකු ණය තහනම් කිරීමට", "තිරසාර දිළිඳුකම තුරන් කිරීම සඳහා ප්‍රාග්ධන ආධාර හා වෘත්තීය පුහුණුව ලබාදීම ඉතා සාර්ථකය."),
    q("වෙළඳපොළේදී පාරිභෝගිකයන්ට 'බර අඩුවෙන් කිරා මැන භාණ්ඩ විකිණීම' වැළැක්වීම සඳහා නියාමනය කරන රාජ්‍ය ආයතනය කුමක්ද?", "මිනුම් ඒකක, ප්‍රමිති හා සේවා දෙපාර්තමේන්තුව සහ පාරිභෝගික අධිකාරිය", "පුරාවිද්‍යා දෙපාර්තමේන්තුව", "ආගමන විගමන දෙපාර්තමේන්තුව", "කාලගුණ විද්‍යා දෙපාර්තමේන්තුව", "වෙළඳසැල්වල තරාදි හා මිනුම් උපකරණ නියමිත කාලසීමාවලදී නිවැරදි බවට පරීක්ෂා කොට මුද්‍රා තැබේ."),
    q("ගෝලීයකරණය හා නවීකරණය මධ්‍යයේ වුවද 'දේශීය සාම්ප්‍රදායික කර්මාන්ත හා කලා ශිල්ප' රැකගත යුත්තේ ඇයි?", "ජාතික සංස්කෘතික අනන්‍යතාව රැකීමට, පරිසර හිතකාමී නිෂ්පාදන බිහිකිරීමට හා සංචාරක ආකර්ෂණයට", "නවීන තාක්ෂණය සම්පූර්ණයෙන් තහනම් කිරීමට", "අපනයන නැවැත්වීමට", "රැකියා අවස්ථා අඩු කිරීමට", "මැටි, පිත්තල, වේවැල්, ලක්ෂා හා අත්යන්ත්‍ර රෙදිපිළි රටේ සංස්කෘතික හා ආර්ථික සම්පතකි."),
    q("සංවර්ධන ව්‍යාපෘතියකදී 'සමාජ බලපෑම් ඇගයීම' (Social Impact Assessment - SIA) මඟින් පරීක්ෂා කරන්නේ කුමක්ද?", "ව්‍යාපෘතිය නිසා ප්‍රදේශයේ ජනතාවගේ ජීවනෝපාය, පදිංචිය, සෞඛ්‍යය හා සංස්කෘතියට ඇතිවන බලපෑම", "කොන්ක්‍රීට් මිශ්‍රණයේ රසායනික සංයුතිය පමණි", "විදේශ විනිමය අනුපාතය පමණි", "වර්ෂාපතන දත්ත පමණි", "ජනතාවගේ ජීවිතවලට වන හානිය අවම කර සාධාරණ වන්දි හා නැවත පදිංචි කිරීම් සැලසුම් කිරීම මෙහි අරමුණයි."),
    q("රටේ සියලු පුරවැසියන්ට ආර්ථික හා සමාජීය අවස්ථා සමානව ලැබීමට බාධා කරන 'සමාජ බැහැර කිරීම' (Social Exclusion) යනු කුමක්ද?", "දිළිඳුකම, ජනවර්ගය, ආබාධිත බව හෝ භාෂාව නිසා ඇතැම් කණ්ඩායම්වලට සමාජ ප්‍රතිලාභ අහිමි වීම", "සියලු දෙනාට සමාන අධ්‍යාපනය දීම", "නොමිලේ සෞඛ්‍ය සේවා සැපයීම", "පොදු ප්‍රවාහන පහසුකම් දියුණු කිරීම", "සැබෑ සංවර්ධනයක් ඇති වන්නේ සමාජයේ ආන්තික කණ්ඩායම්ද ප්‍රධාන ප්‍රවාහයට ඇතුළත් කර ගත් විටය."),
    q("ශ්‍රී ලංකාවේ ප්‍රධාන ආර්ථික අංශ තුන වන 'කෘෂිකර්මය, කර්මාන්ත සහ සේවා' අතුරින් වර්තමානයේ දළ දේශීය නිෂ්පාදිතයට (GDP) වැඩිම දායකත්වයක් දෙන අංශය කුමක්ද?", "සේවා අංශය (වෙළඳාම, බැංකු, ප්‍රවාහනය, සංචාරක, තොරතුරු තාක්ෂණය)", "ප්‍රාථමික ධීවර අංශය පමණි", "වැවිලි අංශය පමණි", "පතල් අංශය පමණි", "ලෝකයේ බොහෝ නවීන ආර්ථිකයන් මෙන්ම ශ්‍රී ලංකාවේද GDP හි 55%කට වැඩි කොටසක් සේවා අංශයෙන් උපදවයි."),
    q("වෙළඳපොළේදී 'නිෂ්පාදකයාගේ වගකීම' යටතේ පාරිභෝගිකයාට ආරක්ෂිත භාණ්ඩ සැපයීමට අනුගමනය කළ යුතු ප්‍රමිතිය කුමක්ද?", "රසායනික විෂ රහිතව, නිසි සෞඛ්‍යාරක්ෂිත තත්ත්ව යටතේ නිෂ්පාදනය කර නිවැරදි තොරතුරු ඇතුළත් කිරීම", "කල් ඉකුත් වූ දිනය මකා දැමීම", "බර අඩු කර ඇසුරුම් කිරීම", "ව්‍යාජ ප්‍රමිති ලාංඡන ගැසීම", "සදාචාරාත්මක ව්‍යාපාරිකයන් ලාභයට වඩා පාරිභෝගික ජීවිත හා සෞඛ්‍ය ආරක්ෂාවට මුල් තැන දේ."),
    q("රටේ පරිසර පද්ධති ආරක්ෂා කිරීමේදී 'ජලාශ හා ගංගා ඉවුරු රක්ෂිත' (River Reservations) තබාගැනීමේ ප්‍රයෝජනය කුමක්ද?", "ජල මූලාශ්‍රවලට අපද්‍රව්‍ය මුසු වීම වැළැක්වීම, ඉවුරු ඛාදනය පාලනය හා ජලජ ජීවීන් රැකීම", "ගං ඉවුරේ හෝටල් ඉදිකිරීමට", "කර්මාන්තශාලා අපද්‍රව්‍ය හෙළීමට", "වැලි කැණීම් වැඩි කිරීමට", "ජල රක්ෂිත ප්‍රදේශවල ගස් වැවීම මඟින් පිරිසිදු ජල සැපයුම දිගුකාලීනව සුරක්ෂිත වේ."),
    q("බහුසංස්කෘතික සමාජයක විවිධ ආගමික ස්ථාන ආරක්ෂා කිරීම සඳහා පුරවැසියන් සතු විය යුතු යුතුකම කුමක්ද?", "තමන්ගේ මෙන්ම අනෙක් සියලු ආගම්වල පූජනීය ස්ථාන හා සංකේතවලට ගරු කිරීම", "අන් ආගමික උත්සවවලට බාධා කිරීම", "ආගමික ගැටුම් අවුලුවාලීම", "වෙනත් ආගමික පොත්පත් විනාශ කිරීම", "ආගමික සහනශීලීතාව සමාජයේ සාමකාමී පැවැත්ම තහවුරු කරන උසස් සිවිල් ගුණාංගයකි."),
    q("තිරසාර සංවර්ධනය උදෙසා 'පාසල් පරිසර නියමු වැඩසටහන' මඟින් සිසුන් තුළ ගොඩනගන්නේ කුමන ආකල්පද?", "සොබාදහමට ආදරය කිරීම, රුක් රෝපණය, ජල-විදුලි සංරක්ෂණය හා පාරිසරික නායකත්වය", "ප්ලාස්ටික් භාවිතය වැඩි කිරීම", "වන සතුන්ට හිංසා කිරීම", "කසළ පන්ති කාමරවල දැමීම", "මධ්‍යම පරිසර අධිකාරිය පාසල් මට්ටමින් ක්‍රියාත්මක කරන මෙම වැඩසටහන හරිත පුරවැසියන් බිහි කරයි."),
    q("රටේ සංවර්ධන කටයුතු සඳහා රජය ලබාගන්නා 'විදේශ ණය' කාර්යක්ෂමව කළමනාකරණය නොකළහොත් ඇතිවන අහිතකර ප්‍රතිඵලය කුමක්ද?", "ණය ගෙවීමේ බර ඉහළ ගොස් ආර්ථික අර්බුද, උද්ධමනය හා සුබසාධන සේවා කප්පාදු ඇති වීම", "සියලු භාණ්ඩ මිල බින්දුවට බැසීම", "රජයේ ආදායම ස්වයංක්‍රීයව ඉහළ යාම", "බදු අය කිරීම අවශ්‍ය නොවීම", "ප්‍රතිලාභ උපදවන ආර්ථික ව්‍යාපෘති සඳහා විනිවිදභාවයෙන් ණය භාවිත කිරීම රටක ස්ථාවරත්වයට අත්‍යවශ්‍යය.")
  )
}
